******************************************************************	Patch to SANE*	for Version 2.0 of ROM***	Copyright (C) 1987*	All Rights Reserved*	Apple Computer, Inc.**** System Disk 2.0** Version 2.1    27	Apr 87    Kenton Hanson & Steven Glass** 20-Dec-90	Dave Lyons** Rolled version to $8300 without changing anything (making* the ROM 1 vs. ROM 3 versions match for 6.0).** 5-Feb-92	Dave Lyons** Version $0300 for 6.0 final.** 6-May-93	Jim Murphy** Version $0301 for 6.0.1 final. Fixed classify bug in FXPWRI.******************************************************************               keep sane2/sane2.objSaneVersionNum	equ $0301ToBusyStrip	equ $E10180ToStrip	equ $E10184;                copy sane2/call.table	EXPORT Sane2CallTableSane2CallTable	PROC	import sanebootinit	import saneversion	import sanepatch	import ElemsPatchTheStart	DC.L (TheEnd-TheStart)/4	DC.L SaneBootInit-1	DC.L 0	; SaneStartup-1'	DC.L 0	; SaneShutdown-1'	DC.L SaneVersion-1	DC.L 0	; SaneReset-1'	DC.L 0	; SaneStatus-1'	DC.L 0	; SaneNotImp-1'	DC.L 0	; SaneNotImp-1'	DC.L SanePatch-1	; Eight16-1'	DC.L 0	; DecStr-1'	DC.L ElemsPatch-1	; Elems816-1TheEnd	ENDP;                copy sane2/patch****************************************************************** SANEPatch** Change history** For System Disk 2.0** Corrects a problem in Comp to X bug for certain large numbers, i.e.* comps that require more than three words to represent their absolute* integer value.  Fix simply zeros word	122 in SANE's zero page work area.** Corrects Muls problem by replacing Muls (or any non MulX)	with a s2x* followed by a mulx.** Fir System Disk 2.1** June 24, 1987  KLH** Fix double rounding error in mulD patch.******************************************************************SANEpatch      PrivateSANEpatch	PROCSANE_Code	equ $FEd3b8OrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3opword	equ RTL2+3LastArg	equ opword+2MidArg	equ LastArg+4x1	equ 246	; last ten bytes of	SANE's direct page	phd	; push direct Register on stack	tcd	; set direct page to SANE's	stz 122	; initialize word in zero page*********************************************************************        above statement corrects large	x to comp error********************************************************************	lda opword,s	; get opword	tax	; save in x	and #$1f	; mask in operation	cmp #$04	; check for multiply	bne done	; not a multiply, done!	txa	; get opword into 'a'	and #$0700	; mask in source's numeric format 	beq done	; mulX, done!	tax	; save source's numeric format	lda MidArg+2,s	; get the msb of the MidArg	pha	; push it onto the stack	lda MidArg+2,s	; get the lsb of the MidArg	pha	; push it onto stack	lda #0	; msb of temp extended address	sta MidArg+6,s	; store it in stack	frame	pha	; push it onto stack	clc	tdc	; Get SANE's direct page	adc #x1	; add relative location in SANE's direct	sta MidArg+6,s	; put lsb of address of x1 into MidArg	pha	; push lsb of address of x1 onto stack	txa	; get source format	code	ora #$000E	; add opword for type to X	pha	lda #$04	; opcode of MulX	sta opword+10,s	; put new opword into stack frame; added to fix double rounding	lda 28	; get enviornment word	and #$C0C0	; mask out precision cntl and rounding	sta 244	; save pc and rd	eor 28	; zero pc and rd	sta 28	; store in store in	env word; end first part of	fix	tdc	; restore 'a' register	jsl ToSANE; second part of fix to rounding	lda 28	; get environment word	ora 244	; restore pc and rd	sta 28	; store in environment word.; end fix.done	tdc	; restore 'a' register	pld	; restore direct Register	jml SANE_Code	ENTRY ToSANEToSANE		;	jsl SANE_Code	; call the real routine	rtl	ENTRY ToSANECodeToSANECode		;	jsl SANE_Code	; call the real routine	rtl	ENDP*** Added - 6-May-93 JCM****************************************************************** ElemsPatch** Change History** 6-May-93 JCM - New for System Disk 6.0.1** Corrects a problem in FXPWRI where <Src_Class was being checked to* see what the integer exponent was classified as without actually having* it classified. This fixes the problem with lockups in the AWGS spreadsheet.*****************************************************************ElemsPatch	PROCElems_Code01	equ $FEEF15	;Elem816 entry point in ROM 01 SANEOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3OpWord	equ RTL2+3DstArg	equ opword+2SrcArg	equ DstArg+4SourceClass	equ $6A	;on SANE DP	phd		tcd	;swap in SANE's DP		lda OpWord,s	;get opword	and #$1F	;just get the operation	cmp #$10	;is it FXPWRI?	bne @doneElemPatch	; aparently not* Assume that the integer exponent is normalized.	ldy #0	;signal normalized	lda SrcArg,s	;get the integer exponent so we can classify it	bne @saveClass	; it's already classified as normalized		dey	;signal it's zero ($FF)@saveClass	sty <SourceClass	;we overwrite Src_Sign, but it doesn't matter@doneElemPatch	tdc	;let SANE know where its DP is	pld	jmp >Elems_Code01	;let SANE do all of the dirty work	ENDP*** End - 6-May-93 JCM****************************************************************** SaneVersion******************************************************************SaneVersion    PrivateSaneVersion	PROCRTL1	equ 1RTL2	equ RTL1+3Result	equ RTL2+3	lda #SaneVersionNum	; get MT version #	sta Result,s	; pass to caller****************************************************************** SaneBootInit*****************************************************************	entry SaneBootInitSaneBootInit	lda #0	clc	rtl	ENDP	END